import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"10、【履】 兑下乾上","description":"周易集注 - 10、【履】 兑下乾上","frontmatter":{"title":"10、【履】 兑下乾上","description":"周易集注 - 10、【履】 兑下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/014.md","filePath":"zh/classics/jizhu/014.md"}'),h={name:"zh/classics/jizhu/014.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_10、【履】-兑下乾上" tabindex="-1">10、【履】 兑下乾上 <a class="header-anchor" href="#_10、【履】-兑下乾上" aria-label="Permalink to “10、【履】 兑下乾上”">​</a></h1><p>履者礼也，以礼人所践履也。其卦兑下干上，天尊于上，泽卑于下，履之象也。内和悦而外刚健，礼严而和之象也。《序卦》“物畜然后有礼，故受之以履”，因次小畜。</p><p>履者足践履也。中爻巽错震，震为足，有履之象，乃自上而履下也。咥者啮也。下卦兑错艮，艮为虎，虎之象也。乃兑为虎，非干为虎也。先儒不知象，所以以干为虎。周公因文王取此象，故革卦上体兑，亦取虎象。曰尾者，因下卦错虎，所履在下，故言尾也。故遁卦下体艮，亦曰尾。兑口乃悦体，中爻又巽顺，虎口和悦，巽顺不猛，故不咥人。</p><p>《彖》曰：履，柔履刚也。说而应乎干，是以履虎尾，不咥人亨。刚中正，履帝位而不疚，光明也。(说音悦)</p><p>以卦德释卦名卦辞，而又言卦体之善。柔履刚者，以三之柔履二之刚也，此就下体自上履下而言也，释卦名也。悦而应乎干者，此就二体自下应上而言也。曰应者，明其非履也。三与五同功，故曰应。此释卦辞之所以亨也。帝指五，九五刚健中正，德与位称，故不疚。不疚则功业显于四方，巍然焕然，故光明。中爻离，光明之象。此又卦体所履之善，非圣人不足以当之，故文王言履虎尾，孔子言履帝位。</p><h3 id="《象》曰-上天下泽-履-君子以辨上下-定民志。" tabindex="-1">《象》曰：上天下泽，履，君子以辨上下，定民志。 <a class="header-anchor" href="#《象》曰-上天下泽-履-君子以辨上下-定民志。" aria-label="Permalink to “《象》曰：上天下泽，履，君子以辨上下，定民志。”">​</a></h3><p>君子观履之象，辨上下之分，上下之分既辨，则民志自定，上自安其上之分，下自安其下之分矣。</p><p>初九，素履，往无咎。</p><p>素者白也空也，无私欲污浊之意。素履即中庸素位而行，舜饭糗茹草，若将终身，颜子陋巷不改其乐是也。往者进也，阳主于进，故曰往。</p><p>初九阳刚在下，本无阴私，当履之初，又无外物所诱，盖素位而行者也，故有素履之象。以是而往，必能守其所愿之志而不变，履之善者也，故占者无咎。</p><h3 id="《象》曰-素履之往-独行愿也。" tabindex="-1">《象》曰：素履之往，独行愿也。 <a class="header-anchor" href="#《象》曰-素履之往-独行愿也。" aria-label="Permalink to “《象》曰：素履之往，独行愿也。”">​</a></h3><p>独，有人所不行而己独行之意。愿即中庸不愿乎外之愿，言初九素位而行，独行己之所愿，而不愿乎其外也。中庸素位二句，盖本周公素履之爻云。</p><p>九二，履道坦坦，幽人贞吉。</p><p>履道坦坦，依乎中庸，不索隐行怪也。幽独之人，多是贤者，过之能履道坦平，不过乎高而惊世骇俗，则贞吉矣。变震为足，履之象也。又为大涂，道坦坦之象也。幽对明言，中爻离明在上，则下爻为幽矣。三画卦二为人位，幽人之象也。故归妹中爻，离九二亦以幽人言之。履以和行，礼之用和为贵，所以本卦阳爻处阴位，如上九则元吉者，以严而有和也。二与四同，二坦坦而四愬愬者，二得中而四不得中也。二与五皆得中位，二贞吉而五贞厉者，二以刚居柔，五以刚居刚也。</p><p>九二刚中居柔，上无应与，故有履道坦坦之象。幽人如此，正而且吉之道也，故占者贞吉。</p><h3 id="《象》曰-幽人贞吉-中不自乱也。" tabindex="-1">《象》曰：幽人贞吉，中不自乱也。 <a class="header-anchor" href="#《象》曰-幽人贞吉-中不自乱也。" aria-label="Permalink to “《象》曰：幽人贞吉，中不自乱也。”">​</a></h3><p>有此中德，心志不自杂乱，所以依中庸而贞吉，世之富贵外物，又岂得而动之。</p><p>六三，眇能视，跛能履。履虎尾，咥人，凶。武人为于大君。</p><p>中爻巽错震足，下离为目，皆为兑之毁折，眇跛之象也。六画卦三为人位，正居兑口，人在虎口之中，虎咥人之象也。三变则六画皆干矣，以悦体而有文明，乃变为刚猛武勇，武之象也。三人位，武人之象也。曰武者，对前未变离之文而言也。阳大阴小，阴变为阳，大之象也。故坤卦用六，以大终变为干君，大君之象也。咥人不咥人之反，为大君，履帝位之反。</p><p>六三不中不正，柔而志刚，本无才德，而自用自专，不能明而强以为明，不能行而强以为行，以此履虎，必见伤害，故有是象。占者之凶可知矣。亦犹履帝位者，必德称其位而不疚，武人乃强暴之夫，岂可为大君哉，徒自杀其驱而已。武人为大君，又占中之象也。</p><h3 id="《象》曰-眇能视-不足以有明也。跛能履-不足以与行也。咥人之凶-位不当也。武人为于大君-志刚也。" tabindex="-1">《象》曰：眇能视，不足以有明也。跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。 <a class="header-anchor" href="#《象》曰-眇能视-不足以有明也。跛能履-不足以与行也。咥人之凶-位不当也。武人为于大君-志刚也。" aria-label="Permalink to “《象》曰：眇能视，不足以有明也。跛能履，不足以与行也。咥人之凶，位不当也。武人为于大君，志刚也。”">​</a></h3><p>不足有明与行，以阴柔之才言。位不当者，以柔居刚也。爻以位为志，六三阴柔，才弱而志刚，亦如师卦之六三，所以武人而欲为大君。</p><p>九四，履虎尾，愬愬，终吉。</p><p>四应初，故履虎尾。愬愬，畏惧貌，四多惧，愬愬之象也。三以柔暗之才，而其志刚猛，所以触祸。四以刚明之才，而其志恐惧，所以免祸。天下之理，原是如此，不独象数然也。</p><p>九四亦以不中不正，履其虎尾，然以刚居柔，故能愬愬戒惧，其初虽不得即吉，而终则吉也。</p><h3 id="《象》曰-愬愬终吉-志行也。" tabindex="-1">《象》曰：愬愬终吉，志行也。 <a class="header-anchor" href="#《象》曰-愬愬终吉-志行也。" aria-label="Permalink to “《象》曰：愬愬终吉，志行也。”">​</a></h3><p>初曰独行，远君也。四曰志行，近君也。志行者，柔顺以事刚决之君，而得行其志也。始虽危而终则不危，所谓终吉者此也。盖危者始平，易之道原是如此，故三之志徒刚，而四之志则行。</p><p>九五，夬履，贞厉。</p><p>夬者决也，慨然以天下之事为可为，主张太过之意。盖夬与履，皆干兑上下相易之卦，曰夬履者，在履而当夬位也。然彖辞与爻辞不同，何也?盖彖辞以履之成卦言，六爻皆未动也。见其刚中正，故善之。爻辞则专主九五一爻而言，以变爻而言也。变离，则又明燥而愈夬矣，故不同。在下位者，不患其不忧，患其不能乐，故喜其履坦在上位者，不患其不乐，患其不能忧，故戒其夬履。二之坦，则正而吉者，喜之也。五之夬，则正而危者，戒之也。</p><p>九五以刚中而履帝位，则有可夬之资，而挟可夬之势矣。又下应巽体，为臣下者皆容悦承顺，故有夬履之象。虽有所恃，必有所害，虽使得正，亦危道也。故其占为贞厉，其戒深矣。</p><h3 id="《象》曰-夬履贞厉-位正当也。" tabindex="-1">《象》曰：夬履贞厉，位正当也。 <a class="header-anchor" href="#《象》曰-夬履贞厉-位正当也。" aria-label="Permalink to “《象》曰：夬履贞厉，位正当也。”">​</a></h3><p>有中正之德而又当尊位，伤于所恃。又下卦悦体，因悦方成其夬，所以兑之九五亦言位正当。</p><p>上九，视履，考祥其旋，元吉。</p><p>视履，作一句，与素履夬履同例。视者回视而详审也，中爻离目，视之象也。祥者善也，三凶五厉，皆非善也。考其履之善，必皆天理之节文，人事之仪则，下文其旋是也。旋者，周旋折旋也。凡礼以义合，而截然不可犯者，谓之方，犹人之步履折旋也。以天合而怡然不可解者，谓之圆，犹人之步履周旋也。礼虽有三千三百之多，不过周旋折旋而已。考其善于周旋折旋之间，则中规中矩矣，岂不元吉。</p><p>上九当履之终，前无所履，可以回视其履矣，故有视履之象。能视其履，则可以考其善矣。考其善而中规中矩，履之至善也。占者如是，不惟吉，而且大吉也。</p><h3 id="《象》曰-元吉在上-大有庆也。" tabindex="-1">《象》曰：元吉在上，大有庆也。 <a class="header-anchor" href="#《象》曰-元吉在上-大有庆也。" aria-label="Permalink to “《象》曰：元吉在上，大有庆也。”">​</a></h3><p>大即元，庆即吉，非元吉之外，别有大庆。</p>',37)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
